ticket_tab_configuration.script:
/**
 * The script should evaluate true/false or `answer` populated with true/false which validates if a tab is visible 
 * The `current` object refers to the current Task(extension) record 
 **/
// Telework Agreement standard ticket page data is visible to:
//	Employee can see their own Telework Agreement
//	Managers can see the Telework Agreements of their employees
//	HR Admins (Groups "CEH-HRS-OHS-Telework-OCHRO", "CEH-HRS-OHS-Telework-HR-IO", "CEH-HRS-OHS-Telework-HR-LR") can see all Telework Agreements
//	Service Area Admins (Group "CEH-HRS-OHS-Telework-ServiceArea") can see Telework Agreements from employees within their Service Area
(function() {
    var loggedInUserId = gs.getUserID();
    var loggedInUser = gs.getUser();
    // HR Admins
    if (loggedInUser.isMemberOf(gs.getProperty('x_hccc_hoc_ohs.telework_group_ochro')) == true)
        return true;
    if (loggedInUser.isMemberOf(gs.getProperty('x_hccc_hoc_ohs.telework_group_hr_io')) == true)
        return true;
    if (loggedInUser.isMemberOf(gs.getProperty('x_hccc_hoc_ohs.telework_group_hr_lr')) == true)
        return true;
    // Service Area Admins
    var userId = gs.getUserID(); // Get Department of logged in User
    var grUser = new GlideRecord('sys_user');
    grUser.get(userId);
    if ((loggedInUser.isMemberOf(gs.getProperty('x_hccc_hoc_ohs.telework_group_service_area')) == true) && (grUser.department.business_unit.toString() == current.employee_service_area.toString())) {
        return true;
    }
    // Managers and Employees
    if ((loggedInUserId == current.manager_name) || (loggedInUserId == current.subject_person))
        return true;

    return false;
})();
